from app.llm import complete
from app.ledger import spend_for_run


def run(goal: str, run_id: str, max_steps: int = 200, ceiling_usd: float = 5.0) -> str:
    """Agent loop bounded by OUR ledger, not only by the provider's refusal."""
    transcript = goal
    for _ in range(max_steps):
        if spend_for_run(run_id) >= ceiling_usd:
            return transcript
        transcript = complete(transcript, run_id=run_id)
        if "DONE" in transcript:
            break
    return transcript
